def selected_action_text(operation, resource, language='fr'):
    en=language=='en'
    return ({'edit':'Edit','delete':'Delete'} if en else {'edit':'Modifier','delete':'Supprimer'})[operation]+' · '+RESOURCE_LABELS[resource][int(en)]
